import{e as r,ab as a,a1 as o,m as s,r as i,p as n}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [March]","description":"March 2025 updates","frontmatter":{"title":"Monthly Updates [March]","description":"March 2025 updates","date":"2025-03-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/mar-2025.md","filePath":"posts/mar-2025.md"}'),l={name:"posts/mar-2025.md"};function h(d,e,p,f,m,g){const t=a("Post");return o(),s("div",null,[i(t,{authors:"nbats"}),e[0]||(e[0]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Re-ordered <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">AI image generators</a> based on <a href="https://challonge.com/xfu596g9" target="_blank" rel="noreferrer">poll results</a>. Thanks to everyone who voted, and congrats to NexusAI Image for coming out on top.</p></li><li><p>Separated <a href="https://fmhy.net/image-tools#image-hosts" target="_blank" rel="noreferrer">Image Hosts</a> &amp; <a href="https://fmhy.net/image-tools#online-galleries" target="_blank" rel="noreferrer">Online Galleries</a> into their own subsections + added size, file retention, and sign-up requirement tags.</p></li><li><p>Split Web Hosting Sites into <a href="https://fmhy.net/storage#dynamic-page-hosting" target="_blank" rel="noreferrer">Dynamic</a>, <a href="https://fmhy.net/storage#static-page-hosting" target="_blank" rel="noreferrer">Static</a>, &amp; <a href="https://fmhy.net/storage#website-builders" target="_blank" rel="noreferrer">Builders</a> + added space, monthly transfer, and traffic tags to each.</p></li><li><p>Separated <a href="https://fmhy.net/internet-tools#rss-tools" target="_blank" rel="noreferrer">RSS Tools</a> &amp; <a href="https://fmhy.net/internet-tools#bookmark-tools" target="_blank" rel="noreferrer">Bookmark Tools</a> into their own subsections.</p></li><li><p>Moved <a href="https://fmhy.net/ai#voice-removal-separation" target="_blank" rel="noreferrer">Voice Removal / Separation</a> from storage to its own section in AI. <a href="https://i.imgur.com/sPqq1v3.png" target="_blank" rel="noreferrer">Before vs. After</a></p></li><li><p>Added mobile optimization scores for all the <a href="https://github.com/fmhy/FMHY/wiki/Stream-Site-Grading" target="_blank" rel="noreferrer">streaming sites</a>.</p></li><li><p>Added tags / labels to the <a href="https://fmhy.net/image-tools#upscale-restore" target="_blank" rel="noreferrer">Image Upscalers</a> section.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="https://fmhy.net/file-tools#file-hosts" target="_blank" rel="noreferrer">files.vc</a> in File Hosts. 10GB per file, no expiration, unlimited files.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#download-managers" target="_blank" rel="noreferrer">AB Download Manager</a> in Download Managers. Manager that is open-source, well-maintained, feature-rich, and nice to look at.</p></li><li><p>Starred <a href="https://fmhy.net/video-tools#video-editors" target="_blank" rel="noreferrer">lossless-cut</a> in Video Editors. Feature-rich editor that preserves quality/metadata for FFmpeg.</p></li><li><p>Starred <a href="https://fmhy.net/video-tools#online-editors" target="_blank" rel="noreferrer">wide.video</a> in Online Video Editors. Feature-rich and stands out a lot compared to similar options.</p></li><li><p>Starred <a href="https://fmhy.net/video#sports-replays" target="_blank" rel="noreferrer">Footballia</a> in Sports Replays. Full classic football matches.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#geoguessr-games" target="_blank" rel="noreferrer">Geotastic</a> in GeoGuessr Games. Seems to stand out compared to similar options.</p></li><li><p>Starred <a href="https://fmhy.net/misc#workout-exercise" target="_blank" rel="noreferrer">DAREBEE + r/BodyweightFitness Wiki</a> in Workout. Multiple fitness routines; both seem to be well-liked by the community.</p></li><li><p>Re-starred <a href="https://fmhy.net/social-media-tools#youtube-downloaders" target="_blank" rel="noreferrer">Stacher</a> in YouTube Downloaders. People felt as though a good yt-dlp GUI was worth having starred again.</p></li><li><p>Starred <a href="https://fmhy.net/ai#voice-removal-separation" target="_blank" rel="noreferrer">UVR5_UI</a> in Voice Removal. Online voice removal tool that seems to work well.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed Malwarebytes crack as it no longer works.</p></li><li><p>Unstarred Go Speed as people don&#39;t feel it&#39;s as good as other options anymore.</p></li></ul>',9))])}const b=r(l,[["render",h]]);export{u as __pageData,b as default};
